import unittest

from candidate import correct_bracketing

class TestCorrectBracketing(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(correct_bracketing(""))

    def test_single_opening_bracket(self):
        self.assertFalse(correct_bracketing("<"))

    def test_single_closing_bracket(self):
        self.assertFalse(correct_bracketing(">"))

    def test_balanced_brackets(self):
        self.assertTrue(correct_bracketing("<>"))

    def test_multiple_balanced_brackets(self):
        self.assertTrue(correct_bracketing("<<><>>"))

    def test_unbalanced_brackets(self):
        self.assertFalse(correct_bracketing("><<>"))

    def test_nested_brackets(self):
        self.assertTrue(correct_bracketing("<<<<>>>>"))

    def test_partial_unbalance(self):
        self.assertFalse(correct_bracketing("<<><>"))

    def test_mixed_brackets(self):
        self.assertFalse(correct_bracketing("><><>"))

    def test_all_opening_brackets(self):
        self.assertFalse(correct_bracketing("<<<<"))

    def test_all_closing_brackets(self):
        self.assertFalse(correct_bracketing(">>>>"))

    def test_non_bracket_characters(self):
        self.assertFalse(correct_bracketing("<a>"))

    def test_none_input(self):
        with self.assertRaises(TypeError):
            correct_bracketing(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            correct_bracketing(123)

    def test_long_balanced_sequence(self):
        self.assertTrue(correct_bracketing("<<<<<<<<>>>>>>>>"))

    def test_long_unbalanced_sequence(self):
        self.assertFalse(correct_bracketing("<<<<<<<<>>>>>>>>><"))

    def test_mixed_with_extra_opening(self):
        self.assertFalse(correct_bracketing("<<><>>><"))

    def test_mixed_with_extra_closing(self):
        self.assertFalse(correct_bracketing("<<><>>><>"))
